INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('owdlhr7bbl4wul7dkvowdlhr6xuprvdl', '2025-Q3', 'Out/2025', '2025-10-06T12:53'::timestamptz, 'Joao Victor Cardoso De Moraes', 'joao victor cardoso de moraes', 'PHARUS', 'Rodrigo Lunardi', 9.0, 'Promotor', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'Acredito muito no conhecimento técnico transmitido pelos profissionais envolvidos. Como a parceria é recente e os resultados naturalmente lentos, ainda tenho uma ponta de insegurança', NULL, 'O entendimento transmitido sobre construção de riqueza. Acredito que poderia ter mais aulas pra aumentar a compreensão', 'Resultados rápidos e um fluxo de capital maior do que eu faço atualmente', 'Estou um pouco inseguro com o processo. Parecia que a estratégia dos consórcios seria mais rápida (sei que não é bem assim, mas expectativa criada foi maior). Algumas oportunidades de investimento ocorrem apenas dentro da plataforma da quartavia e isso me deixa inseguro e de certa forma dependente demais do sistema. Meu ganho mensal com meu trabalho parece estar aquém de deixar tranquilo para que eu possa fazer dívidas boas, não me sinto confiante em fazer tantos compromissos financeiros', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'owdlhr7bbl4wul7dkvowdlhr6xuprvdl', 'cadastro 2026-T2 (281 dias)', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('rrpjme93p2wbcorrpjmegyrtk0ep4tzg', '2025-Q3', 'Out/2025', '2025-10-08T10:46'::timestamptz, 'Valdecir Augusto Ribeiro Ferreira', 'valdecir augusto ribeiro ferreira', 'PHARUS', 'Hendrick Ramos', 8.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Totalmente no caminho', 'Tenho clareza e estou executando com consistência', 'Creio que se enquadra ao contexto empresarial para inicio de entendimento em relação a escala patrimonio para empresarios sem a devida amplitude ou entendimento do tema.', 'Melhorar o onboarding do cliente ou mesmo remeter relatorios periodicos de avanço ou piora da saude financeira e plano do cliente', NULL, 'Um plno bem definido de onde posso chegar mediante minha situação atual de hoje, comprovando em calculos praticos que em 05 anos eu teria minha independencia financeira pela renda passiva', 'Tinha duvidas em relação a alavancagem patrimonial, muitos mitos estão existentes no mercado, mas, o fato é que as melhores praticas estão fechadas dentro de um grupo de açoes e demandam pratica sobre elas. Creio que algumas estrategias mais arrojadas estão ocultas para o publico que está no Davus, e a estrategia está corretissima, mas, em menor escala tambem podem ser utilizadas em quem está no Pharus. Por fim, eu respeito o preço do conhecimento e ter ciencia do caminho a ser percorrido, o vlor investido já é valido.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'rrpjme93p2wbcorrpjmegyrtk0ep4tzg', 'pharus 2 (75 dias)', 'NPS (PHARUS)') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('pcd7y1lahmrrmd36xpcd7y126xt0m3g3', '2025-Q3', 'Out/2025', '2025-10-09T14:31'::timestamptz, 'Bruno Tubino Noronha', 'bruno tubino noronha', 'PHARUS', NULL, 6.0, 'Detrator', 8.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Entendi o método, mas ainda não implementei o suficiente', 'A execução da principal estratégia não depende apenas de si, mas de ter familiares ou pessoas próximas em condições de adquirir seu imóvel', 'Mais estratégias que não dependam da comprovação de renda de terceiros', NULL, 'Iniciar uma boa estratégia de consórcio, pagar bem menos na renovação do Pharus', 'Gabriel explicou bem o método todo, atende muito bem. Porém, estou há meses aguardando surgir uma carta contemplada de 100 mil. Além disso, a principal razão que me fez entrar no programa foi a promessa de entrar em uma estratégia de consórcio que aceitasse o FGTS como lance, mesmo já tendo o utilizado para quitar o imóvel onde moro (isso afirmado pelo atendente que me convenceu a entrar no Pharus). Contudo, Gabriel já me informou que isso é impossível.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'pcd7y1lahmrrmd36xpcd7y126xt0m3g3', 'pharus 2 (77 dias)', NULL) ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('rmakva26tra39k3jjoo3rmakvm89740f', '2025-Q3', 'Out/2025', '2025-10-13T19:45'::timestamptz, 'Ana Maria Soria', 'ana maria soria', 'PHARUS', 'Cleuber Anicesio', 5.0, 'Detrator', 7.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Tenho clareza e estou executando com consistência', 'Só eu estou cumprindo o combinado , até agora não recebi nenhuma indicação para aumentar meu patrimônio', 'Me ajudar na construção do meu patrimônio Cf combinado, estou só na fase de poupar.', NULL, 'Ter resultados financeiros concretos', 'Meu estrategista é muito bonzinho, excelente pessoa, atencioso mas não me trouxe as oportunidades prometidas', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'rmakva26tra39k3jjoo3rmakvm89740f', 'cadastro 2026-T2 (274 dias)', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('6zup68pt8jqqt6zrtm0ddftdspxgyakh', '2025-Q3', 'Out/2025', '2025-10-17T15:00'::timestamptz, 'Marcus Castilho Monteiro', 'marcus castilho monteiro', 'PHARUS', 'Tiago Junior', 8.0, 'Neutro', 10.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Entendi o método, mas ainda não implementei o suficiente', 'A proposta é excelente, as ideias são muito boas, mas ainda não pudemos aproveitar todo esse potencial. Em parte porque ainda estamos em uma fase de reestruturação financeira, e por isso não estamos vendo o retorno esperado. Porém estamos evoluindo e as orientações têm sido todas de grande valor.', 'Espero chegar nesta nota e até maiores quando efetivamente eu conseguir observar os resultados. Como disse, as ideias são ótimas, mas ainda não puderam ser aplicadas efetivamente no nosso caso.', NULL, 'Obter os resultados esperados com a execução dos planos de alavancagem, renda passiva, etc', 'No geral estou satisfeito, mas ainda inseguro pois não obtive resultados ainda. Isso dá uma certa insegurança, principalmente por ter como única solução no momento a contratação de um Home Equity que por hora só representa uma despesa (alta) a mais. Mas tenho certeza que os investimentos que farei com a orientação de vocês serão os mais indicados para multiplicar meu capital.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '6zup68pt8jqqt6zrtm0ddftdspxgyakh', 'MARÇO (156 dias)', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
